<template><section class="suite-page"><div class="suite-titlebar"><div><h1>提示词中心</h1><p>共 {{ prompts.length }} 条提示词，按标题、标签与分类快速查找灵感。</p></div><button class="suite-btn primary" @click="openCreate">新增提示词</button></div><div class="suite-filters"><input v-model="query" class="suite-input suite-search" placeholder="按标题或内容查询"><select v-model="category" class="suite-select"><option value="">全部分类</option><option v-for="item in categories" :key="item">{{ item }}</option></select><button class="suite-btn" @click="downloadJson('canvas-prompts.json',prompts)">导出</button><button class="suite-btn" @click="fileInput?.click()">导入</button><input ref="fileInput" hidden type="file" accept="application/json" @change="importPrompts"></div><div v-if="filtered.length" class="suite-grid"><article v-for="item in filtered" :key="item.id" class="suite-card prompt-card"><span>{{ item.category||'未分类' }}</span><h2>{{ item.title }}</h2><p>{{ item.content }}</p><div class="prompt-tags"><span v-for="tag in item.tags" :key="tag">#{{ tag }}</span></div><div class="suite-card-actions"><button class="suite-btn" @click="usePrompt(item)">去生图</button><button class="suite-btn" @click="edit(item)">编辑</button><button class="suite-btn danger" @click="remove(item.id)">删除</button></div></article></div><div v-else class="suite-empty">没有找到匹配的提示词</div><div v-if="showForm" class="suite-modal-backdrop" @click.self="showForm=false"><div class="suite-modal"><h2>{{ draft.id?'编辑提示词':'新增提示词' }}</h2><div class="suite-form"><label>标题<input v-model="draft.title" class="suite-input"></label><label>分类<input v-model="draft.category" class="suite-input" placeholder="海报、人物、商品等"></label><label>标签<input v-model="tags" class="suite-input" placeholder="多个标签用逗号分隔"></label><label>提示词<textarea v-model="draft.content" class="suite-textarea" rows="8"></textarea></label><div class="suite-form-actions"><button class="suite-btn" @click="showForm=false">取消</button><button class="suite-btn primary" :disabled="!draft.title.trim()||!draft.content.trim()" @click="save">保存</button></div></div></div></div></section></template>
<script setup lang="ts">import {computed,ref} from 'vue';import {useRouter} from 'vue-router';import {canvasStorage,downloadJson,makeId,readJsonFile,type PromptItem} from './storage';const router=useRouter(),prompts=ref(canvasStorage.prompts()),query=ref(''),category=ref(''),showForm=ref(false),tags=ref(''),fileInput=ref<HTMLInputElement|null>(null);const blank=():PromptItem=>({id:'',title:'',content:'',category:'',tags:[],createdAt:new Date().toISOString()});const draft=ref(blank());const categories=computed(()=>[...new Set(prompts.value.map(p=>p.category).filter(Boolean))]);const filtered=computed(()=>{const q=query.value.toLowerCase();return prompts.value.filter(p=>(!category.value||p.category===category.value)&&(!q||[p.title,p.content,...p.tags].join(' ').toLowerCase().includes(q)))});function persist(){canvasStorage.savePrompts(prompts.value)}function openCreate(){draft.value=blank();tags.value='';showForm.value=true}function edit(p:PromptItem){draft.value=structuredClone(p);tags.value=p.tags.join(', ');showForm.value=true}function save(){const value={...draft.value,id:draft.value.id||makeId('prompt'),tags:tags.value.split(/[,，]/).map(v=>v.trim()).filter(Boolean)};const i=prompts.value.findIndex(p=>p.id===value.id);if(i>=0)prompts.value[i]=value;else prompts.value.unshift(value);persist();showForm.value=false}function remove(id:string){if(confirm('确定删除这条提示词吗？')){prompts.value=prompts.value.filter(p=>p.id!==id);persist()}}function usePrompt(p:PromptItem){sessionStorage.setItem('jkapi_canvas_pending_prompt',p.content);void router.push('/canvas/image')}async function importPrompts(e:Event){const input=e.target as HTMLInputElement,file=input.files?.[0];if(!file)return;const v=await readJsonFile<PromptItem[]>(file);if(Array.isArray(v)){prompts.value=v;persist()}input.value=''}</script>
<style scoped>.prompt-card{min-height:230px;display:flex;flex-direction:column}.prompt-card>span{font-size:12px;color:#777}.prompt-card p{white-space:pre-wrap;display:-webkit-box;-webkit-line-clamp:5;-webkit-box-orient:vertical;overflow:hidden}.prompt-tags{display:flex;gap:7px;color:#5d6875;font-size:12px;margin-top:12px}.suite-card-actions{margin-top:auto}</style>
